"""Produce a measurement-only handover report from completed receipts."""
from common import *
def main():
 cfg();device=json.loads((D/'environment.json').read_text());table3=json.loads((D/'tables/table3.json').read_text())['rows'];ok=[r for r in table3 if r.get('completeness') is not None];missing=[r for r in table3 if r.get('completeness') is None];tau=json.loads((D/'tables/table1_tau.json').read_text())['rows'];repro=json.loads((D/'tables/reproduction_full_replay.json').read_text())['rows'];timings=[json.loads(p.read_text()) for p in (O/'timing').glob('*.json')];primary=[r for r in timings if not r.get('stage','').startswith('bounded_cleanup_')];first=next((r for r in timings if r.get('stage')=='bounded_cleanup_B173nb_b10__ALS__r8_30000'),None);primary+=([first] if first is not None and not any(r.get('stage')=='B173nb_b10__ALS__r8_30000_final_finish' for r in timings) else []);seconds=sum(float(r.get('seconds',0)) for r in primary);wait=sum(float(r.get('gpu_wait_seconds',0)) for r in primary);elapsed=(dt.datetime.fromisoformat(now())-dt.datetime.fromisoformat(json.loads((C/'rescore_v1.initial.lock.json').read_text())['at'])).total_seconds()
 lines=[f"다시 센 판: 장면 전체 {len(ok)}줄. 확인 불가 {len(missing)}줄. [이 발주에서 냄]",'새 τ(cm): B0 LoD2 27.1759/64.2505, 항공 LiDAR 14.7374; B173 주변·B173만 LoD2 24.7020/39.2314, 항공 LiDAR 21.1856; R1 LoD2 85.4808/100.5506, 항공 LiDAR 13.2245. LoD2 순서는 지붕/벽.',f"옛 규칙 재현: 두 판 모두 0.1 %p·0.1 cm 이내. 최대 절대차 {max(abs(d) for r in repro for d in r['delta']):.5f} (비율은 %p, 거리는 cm).",'확인 불가: LoD2 r8 30,000회 없음(본문 임시는 7,000회). B173만의 JUDGEAPPLY 핵심점·MVS 입력 표면·기준선 없음. TSDF의 학습/가상 시점별 오차 면 기여는 확인 불가.',f"전체 벽시계 {elapsed/3600:.3f}시간, 중첩 하위 단계를 뺀 단계 시간 합 {seconds/3600:.3f}시간, GPU 대기 {wait/3600:.3f}시간. 병렬 단계 합으로 벽시계 시간과 다르다. {device['cpu_model']}, RTX 3090 두 장(상세 environment.json). nice 19·프로세스 32 GiB 이하, 채점 CPU 상한 16. GPU는 저장 모델 깊이 렌더링에만 사용.",'','# 다시 채점 보고 v1','','학습 없음. scientific_verdict: null. 해석을 덧붙이지 않는다. 수치는 표 파일의 반올림 전 값과 표본 수에 연결된다.','', '## 목록과 범위','','단계0_목록.md와 stage0_inventory(48줄), stage0_patch_scope, stage0_fusion에 저장 상태와 입력 계보를 기록했다. r8은 옛 판단으로 학습한 임시값이다. 2DGS는 사전 정보 없는 동일 저장 모델·메시를 두 사전 정보로 센다. GeoGS는 고친 공식 구현, CDGS는 7장 숫자 작업의 크기 맞추기 생략 판이다. CDGS 학습 씨앗은 고정되지 않았고 영상 분할만 42다.','', '## τ와 칸','','표 1(table1_tau)은 앞 작업의 같은 잔차를 사용하고 3 NMAD 제거만 없앴다. τ 계산에 참값을 사용하지 않았다. 표 2(table2_cells)는 JUDGEAPPLY 핵심점과 patch_id로 정확히 연결한 6개 파일의 새 칸이다. 기존 정상 범위 밖 기하(칸 9)는 칸 6으로 바꾸지 않았다. B173만은 핵심점이 없어 칸을 만들지 않았다. 표 7.1은 계산하지 않았다.','', '## 재현과 메시 점검','','실제 옛 학습 시점 메시를 400점/m²·seed 0으로 다시 표본화하고 거리까지 계산한 재현은 다음과 같다.','','| 판 | 완전성 % | 정확성 % | 참값 거리 cm | 결과 거리 cm |','|---|---:|---:|---:|---:|']
 for r in repro:lines.append('| '+r['key']+' | '+' | '.join(f'{x:.5f}' for x in r['actual'])+' |')
 lines+=['','재현은 옛 단일 τ 14.7 cm와 거리 제한 없는 가까운 패치 규칙이다. 나머지는 새 τ·칸·기둥 규칙이다. LoD2 벽 τ 선택 오류를 발견해 결과 면 종류에 맞게 수정했다. 수정 전 값은 각 score의 values.before_wall_tau.json과 tau.before_wall_correction.npz로 보존했다. 완료된 네 LoD2 판은 저장된 거리·좌표로 재집계했다(tables/wall_tau_recount). 원래 float64 평균 거리는 보존했다.','', '표 9(table9)는 B173 주변 r8/기준선의 학습 시점, 공통 시점의 옛 설정(0.10/0.50 m), 새 설정(0.05/0.25 m) 메시를 비교한다. LoD2 r8 30,000회는 결측 상태 그대로다. 항공 LiDAR 결합의 옛 메시와 새 패치 조합 메시도 포함한다. 학습 시점 메시 중 동일 0.05/0.25 m·학습 시점 수·상자 조건이 확인된 원본은 바이트를 복사해 재사용했다(training_mesh_reuse_*).','', '최종 메시의 큰 연결 성분 거르기는 원본의 50번째 크기 문턱과 최소 50삼각형, 동률 포함 규칙을 따른다. 메모리 제한을 위해 같은 공유 변 연결 계산을 C++로 옮겼으며 원본과 정점/삼각형 동일성을 한 번 확인했다. CDGS 대형 메시 병합은 디스크 배열과 나눈 순열 계산으로 메모리를 제한했다. 전역 edge와 미확정 vertex fallback 두 사례에서 기존 병합과 PLY 바이트·vertex 메타데이터가 일치했다(bounded_merge_validation). 초기 병합의 receipt 누락과 원본 정리 프로세스 종료는 issues.md에 기록했고 원본 파일을 고치지 않았다.','', '## 표 3~8','','B173 주변 항공 LiDAR의 장면 전체 값은 다음과 같다. r8은 옛 판단으로 학습한 임시값이다.','','| 판 | 완전성 % | 정확성 % | 참값 거리 cm | 결과 거리 cm |','|---|---:|---:|---:|---:|']
 for r in ok:
  if r['site']=='B173nb_b10' and r['prior']=='ALS':lines.append('| '+r['method']+' | '+' | '.join(f'{100*r[k]:.4f}' for k in ['completeness','accuracy','gt_mean_m','result_mean_m'])+' |')
 lines+=['','전체 지역·두 사전 정보는 tables/table3(장면), table4(맞는 판단), table5(어긋남), table6(판단 목표와 결과), table7(기준선·조합·임시 r8·상한), table8(둘 다 틀린 곳의 2 m 띠)을 본다. 기둥 밖·중복·지붕 기둥에서 벽 참값이 더 가까운 비율, 유효 참조에서 제외된 비율을 표 3·4에 함께 기록했다. 결과 점 수는 유효 참조 수와 전체 표본 수를 구분했다.','', '입력 사전 정보는 main_stage1_v1/defs/<지역>/prior_<사전 정보>.npz의 원래 V/F다. 입력 MVS는 main_axes71_v2/mvs/<지역>/mesh_mvs_a.ply다. JA 높이로 입력 표면을 만들지 않았다. 새 표본과 거리를 다시 계산했고, LoD2 네 판의 벽 τ 수정 때만 저장된 거리·좌표를 재집계했다. 모든 정확한 면 경로와 SHA-256은 표 3의 surface, surface_sha256 및 score의 input_surface에 있다.','', '칸 0의 완전성이 기준선보다 30 %p 넘게 낮은 비교 방법은 low_cell0_*와 low_cell0_mesh_comparison_*에 학습 시점/최종 값을 기록하고, 같은 대표 학습 시점에서 렌더 깊이와 참값 점의 깊이를 그렸다. 까닭은 추정하지 않았다.','', '## 학습 없는 목표','','판단으로 조합한 메시와 상한은 targets_v2/targets_oracle에서 0.25 m 사각형을 만들고 공통 시점과 같은 TSDF·거르기를 썼다. 일치 목표에는 두 자료의 정밀도만 사용하고 σ_W와 r을 더하지 않았다. 미판정은 광도 일관성 검사와 사전 정보별 기본 판단을 따르며, 보정으로 간 미판정의 σ는 비워 두었다.','']
 for p in sorted((D/'tables').glob('target_diagnostics_*.json')):
  for r in json.loads(p.read_text())['rows']:
   c=r['training_v2_comparison'];lines.append(f"- {r['site']} {r['prior']}: 미판정 {r['undecided_area_m2']:.4f} m², 목표가 있고 σ가 없는 넓이 {r['sigma_missing_area_m2']:.4f} m². 학습 목표 높이 대조 {c['status'] if isinstance(c,dict) else c}"+(f", 최대 {c['max_height_difference_m']:.9f} m." if isinstance(c,dict) and c.get('status')=='PASS' else '.'))
   ft=r.get('finaltrain_target_comparison',{});lines.append(f"  FINALTRAIN 목표 높이 대조: {ft.get('status','확인 전')}"+(f", 최대 {ft['max_height_difference_m']:.9f} m." if ft.get('status')=='PASS' else '.'))
 lines+=['','FINALTRAIN 파일이 있으면 source_index로 목표 높이를 대조했다. FINALTRAIN의 학습용 σ 대체는 이 발주의 빈 σ에 복사하지 않았다. 상한은 칸 0·1·2·4만 명시된 입력을 고르고 칸 3·5·6·9는 본 방법의 목표를 유지한다.','', '## 그림','','그림은 figures.py 하나가 만들며 사용 판, 자리, 시점, 색과 출처를 같은 이름의 JSON에 기록했다. 7.3·7.5는 항공 LiDAR와 LoD2 모두 같은 A/B/C 자리를 사용한다. LoD2 B는 그 자리의 지배적인 칸 3 이름을 쓴다. 칸 아래 값은 잘라낸 자리의 값이 아닌 맞는 판단 영역 전체 값이다.','']
 for p in sorted((D/'figures').glob('*.json')):
  r=json.loads(p.read_text());lines.append(f"- {p.stem}: {r.get('title',p.stem)}. 300 dpi; 출처·좌표는 {p.name}.")
  if 'source_scores' in r:
   vv=[json.loads((O/'scores'/k/'values.json').read_text()) for k in r['source_scores']];lines.append('  완전성/정확성(%): '+'; '.join(f"{x['scene']['completeness']*100:.2f}/{x['scene']['accuracy']*100:.2f}" for x in vv)+'.')
  elif 'places' in r and r['places'] and isinstance(r['places'][0],dict) and 'metrics_entire_cell' in r['places'][0]:
   lines.append('  영역 전체 값(A/B는 %, C는 cm): '+'; '.join(x['place']['id']+' '+', '.join(f"{m['value']*100:.2f}" if m['value'] is not None else '확인 불가' for m in x['metrics_entire_cell']) for x in r['places'])+'.')
  elif 'rows' in r and r['rows'] and 'cell1' in r['rows'][0]:lines.append('  칸 1/2 완전성(%): '+'; '.join(f"{x['cell1']:.2f}/{x['cell2']:.2f}" for x in r['rows'])+'.')
  elif 'rows' in r and r['rows'] and 'cell2' in r['rows'][0]:lines.append('  기준선/본 방법 보존 영역 완전성(%): '+', '.join(f"{x['cell2']['completeness']*100:.2f}" for x in r['rows'])+'.')
  elif 'range_m' in r:lines.append(f"  공통 색 막대: {r['range_m'][0]:.4f}~{r['range_m'][1]:.4f} m.")
  else:lines.append('  '+('입력 단면 4개, 학습 결과 0개.' if p.stem=='그림6_2' else '같은 학습 시점의 결과 깊이/참값 깊이 2개.'))
 lines+=['','## 바꾼 것과 확인 불가','','변경은 이 발주의 τ 제거 규칙, 결과 면, 기둥 소속, 목표와 표시 규칙 및 구현 오류 수정에 한정했다. 옮긴 원본 함수와 변경 사유는 각 스크립트·사용법·issues.md에 기록했다. τ 수정 전 입력과 원래 결과는 읽기 전용이었다. B173만은 기존 식으로 참값 법선을 이 발주 출력에서 계산해 장면 전체만 셌으며, 없는 JUDGEAPPLY 칸·기둥 값은 비워 두었다. 원본 MVS 표면·기준선이 없는 항목도 확인 불가다.','',f'시간 어림은 첫 최종 메시의 실측으로 10.9808시간이었다. 덧붙임 1에 따라 멈추지 않았다. 각 단계 실측과 GPU 대기는 timing_summary.json과 progress.md에 있다. 최종 점검과 묶음 검사는 final_validation.json, package_receipt.json에 별도로 기록한다.']
 text='\n'.join(lines)+'\n';assert len(text)<=15000,len(text);(D/'다시채점_보고_v1.md').write_text(text);dump(D/'timing_summary.json',dict(rows=timings,summed_stage_seconds=seconds,wall_clock_seconds=elapsed,gpu_wait_seconds=wait,parallel_sum_not_wall_clock=True,scientific_verdict=None));print('REPORT_CHARS',len(text))
if __name__=='__main__':main()
